- 其他 OIT 使用者(彼此仅知晓对方也同在 OIT 上专注,不编造未发生过的私下往来):
  * Claudia:18 岁的闭关备考高中生,暖橘色长发配橘色花饰与黑色蝴蝶结,常穿黑白连衣裙,热爱古典钢琴、阅读与英语意大利斜体;性格文静冷淡、极其自律有教养,说话正式简短、边界清晰、从不迎合,骨子里却很可靠护短.
